/// GET /mail/messages/stats/size-count-by-tier — COUNT mensagens por faixa de size. Sprint #1877.
async fn size_count_by_tier_stats(
    State(state): State<AppState>,
    ctx:          RequestCtx,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    let mut tx = begin_tenant_tx(state.db(), ctx.tenant_id).await?;
    let rows: Vec<(String, i64)> = sqlx::query_as(
        "SELECT CASE \
           WHEN size_bytes = 0 THEN 'empty' \
           WHEN size_bytes < 1024 THEN 'tiny' \
           WHEN size_bytes < 10240 THEN 'small' \
           WHEN size_bytes < 102400 THEN 'medium' \
           WHEN size_bytes < 1048576 THEN 'large' \
           ELSE 'huge' END AS tier, \
         COUNT(*)::BIGINT AS message_count \
         FROM messages m JOIN mailboxes mb ON mb.id = m.mailbox_id \
         WHERE m.tenant_id = $1 AND mb.tenant_id = $1 AND mb.user_id = $2 \
         GROUP BY tier ORDER BY message_count DESC",
    )
    .bind(ctx.tenant_id)
    .bind(ctx.user_id)
    .fetch_all(&mut *tx)
    .await?;
    tx.commit().await?;
    let result: Vec<serde_json::Value> = rows
        .into_iter()
        .map(|(tier, cnt)| serde_json::json!({"tier": tier, "message_count": cnt}))
        .collect();
    Ok(Json(serde_json::json!({"rows": result})))
}

/// GET /mail/messages/stats/size-histogram — distribuição de tamanhos em buckets de 10KB. Sprint #1882.
async fn size_histogram_stats(
    State(state): State<AppState>,
    ctx:          RequestCtx,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    let mut tx = begin_tenant_tx(state.db(), ctx.tenant_id).await?;
    let rows: Vec<(i64, i64)> = sqlx::query_as(
        "SELECT (size_bytes / 10240) AS bucket_10kb, COUNT(*)::BIGINT AS message_count \
         FROM messages m JOIN mailboxes mb ON mb.id = m.mailbox_id \
         WHERE m.tenant_id = $1 AND mb.tenant_id = $1 AND mb.user_id = $2 \
         GROUP BY bucket_10kb ORDER BY bucket_10kb ASC \
         LIMIT 100",
    )
    .bind(ctx.tenant_id)
    .bind(ctx.user_id)
    .fetch_all(&mut *tx)
    .await?;
    tx.commit().await?;
    let result: Vec<serde_json::Value> = rows
        .into_iter()
        .map(|(bucket, cnt)| serde_json::json!({"bucket_10kb": bucket, "range_start_bytes": bucket * 10240, "message_count": cnt}))
        .collect();
    Ok(Json(serde_json::json!({"rows": result})))
}

/// GET /mail/messages/stats/size-p05-by-tier — P05 size_bytes × tier. Sprint #3853.
async fn size_p05_by_tier_stats(
    State(state): State<AppState>,
    ctx:          RequestCtx,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    let mut tx = begin_tenant_tx(state.db(), ctx.tenant_id).await?;
    let rows: Vec<(String, i64, i64)> = sqlx::query_as(
        "SELECT CASE WHEN m.size = 0 THEN 'empty' \
                     WHEN m.size < 1024 THEN 'tiny' \
                     WHEN m.size < 10240 THEN 'small' \
                     WHEN m.size < 102400 THEN 'medium' \
                     WHEN m.size < 1048576 THEN 'large' \
                     ELSE 'huge' END AS tier, \
         PERCENTILE_CONT(0.05) WITHIN GROUP (ORDER BY m.size)::BIGINT AS p05_size_bytes, \
         COUNT(*)::BIGINT AS message_count \
         FROM messages m JOIN mailboxes mb ON mb.id = m.mailbox_id \
         WHERE m.tenant_id = $1 AND mb.tenant_id = $1 AND mb.user_id = $2 \
         GROUP BY tier ORDER BY p05_size_bytes DESC",
    )
    .bind(ctx.tenant_id)
    .bind(ctx.user_id)
    .fetch_all(&mut *tx)
    .await?;
    tx.commit().await?;
    let result: Vec<serde_json::Value> = rows
        .into_iter()
        .map(|(tier, p05, cnt)| serde_json::json!({"tier": tier, "p05_size_bytes": p05, "message_count": cnt}))
        .collect();
    Ok(Json(serde_json::json!({"rows": result})))
}

