    let result: Vec<serde_json::Value> = rows.into_iter().map(|(sender, total, cnt)| {
        serde_json::json!({"sender": sender, "total_size": total, "count": cnt})
    }).collect();
    Ok(Json(serde_json::json!({"grand_total_size": grand_total, "rows": result})))
