/// GET /mail/messages/stats/recipient-count-trimmed-mean-by-sender — média aparada de recipient_count por remetente. Sprint #3493.
async fn recipient_count_trimmed_mean_by_sender_stats(
    State(state): State<AppState>,
    ctx: RequestCtx,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    let mut tx = state.begin_tenant_tx(ctx.tenant_id).await.map_err(|e| {
        (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()})))
    })?;
    let rows: Vec<(String, Vec<Option<i32>>, i64)> = sqlx::query_as(
        "SELECT m.from_addr AS sender, \
                ARRAY_AGG(m.recipient_count ORDER BY m.recipient_count) AS counts, \
                COUNT(*)::BIGINT AS msg_count \
         FROM messages m JOIN mailboxes mb ON m.mailbox_id = mb.id \
         WHERE m.tenant_id = $1 AND m.user_id = $2 \
         GROUP BY m.from_addr ORDER BY msg_count DESC LIMIT 100",
    ).bind(ctx.tenant_id).bind(ctx.user_id).fetch_all(&mut *tx).await
    .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    tx.commit().await.map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    let result: Vec<serde_json::Value> = rows.into_iter().map(|(sender, raw, cnt)| {
        let mut vals: Vec<f64> = raw.into_iter().flatten().map(|v| v as f64).collect();
        vals.sort_unstable_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        let n = vals.len();
        let trimmed_mean = if n < 2 { vals.first().copied().unwrap_or(0.0) } else {
            let trim = (n as f64 * 0.1).floor() as usize;
            let t = &vals[trim..n.saturating_sub(trim)];
            if t.is_empty() { 0.0 } else { t.iter().sum::<f64>() / t.len() as f64 }
        };
        serde_json::json!({"sender": sender, "trimmed_mean_recipient_count": trimmed_mean, "message_count": cnt})
    }).collect();
    Ok(Json(serde_json::json!({"rows": result})))
}

/// GET /mail/messages/stats/recipient-count-winsorized-mean-by-sender — média winsorizada de recipient_count por remetente. Sprint #3494.
async fn recipient_count_winsorized_mean_by_sender_stats(
    State(state): State<AppState>,
    ctx: RequestCtx,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    let mut tx = state.begin_tenant_tx(ctx.tenant_id).await.map_err(|e| {
        (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()})))
    })?;
    let rows: Vec<(String, Vec<Option<i32>>, i64)> = sqlx::query_as(
        "SELECT m.from_addr AS sender, \
                ARRAY_AGG(m.recipient_count ORDER BY m.recipient_count) AS counts, \
                COUNT(*)::BIGINT AS msg_count \
         FROM messages m JOIN mailboxes mb ON m.mailbox_id = mb.id \
         WHERE m.tenant_id = $1 AND m.user_id = $2 \
         GROUP BY m.from_addr ORDER BY msg_count DESC LIMIT 100",
    ).bind(ctx.tenant_id).bind(ctx.user_id).fetch_all(&mut *tx).await
    .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    tx.commit().await.map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    let result: Vec<serde_json::Value> = rows.into_iter().map(|(sender, raw, cnt)| {
        let mut vals: Vec<f64> = raw.into_iter().flatten().map(|v| v as f64).collect();
        vals.sort_unstable_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        let n = vals.len();
        let winsorized_mean = if n < 2 { vals.first().copied().unwrap_or(0.0) } else {
            let p10 = vals[(n as f64 * 0.10) as usize];
            let p90 = vals[((n as f64 * 0.90) as usize).min(n - 1)];
            let clamped: Vec<f64> = vals.iter().map(|&v| v.clamp(p10, p90)).collect();
            clamped.iter().sum::<f64>() / clamped.len() as f64
        };
        serde_json::json!({"sender": sender, "winsorized_mean_recipient_count": winsorized_mean, "message_count": cnt})
    }).collect();
    Ok(Json(serde_json::json!({"rows": result})))
}

