/// GET /mail/messages/stats/attachment-count-atkinson-by-folder — índice Atkinson de attachment_count por pasta. Sprint #3355.
async fn attachment_count_atkinson_by_folder_stats(
    State(state): State<AppState>,
    ctx: RequestCtx,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    let mut tx = state.begin_tenant_tx(ctx.tenant_id).await.map_err(|e| {
        (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()})))
    })?;
    let rows: Vec<(String, Vec<Option<i32>>, i64)> = sqlx::query_as(
        "SELECT mb.name AS folder, \
                ARRAY_AGG(m.attachment_count ORDER BY m.attachment_count) AS counts, \
                COUNT(*)::BIGINT AS msg_count \
         FROM messages m JOIN mailboxes mb ON m.mailbox_id = mb.id \
         WHERE m.tenant_id = $1 AND m.user_id = $2 \
         GROUP BY mb.name ORDER BY mb.name",
    ).bind(ctx.tenant_id).bind(ctx.user_id).fetch_all(&mut *tx).await
    .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    tx.commit().await.map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    let result: Vec<serde_json::Value> = rows.into_iter().map(|(folder, raw, cnt)| {
        let vals: Vec<f64> = raw.into_iter().flatten().map(|v| v as f64).filter(|&v| v > 0.0).collect();
        let n = vals.len();
        let atkinson = if n == 0 { 0.0 } else {
            let mean = vals.iter().sum::<f64>() / n as f64;
            let geo_mean = (vals.iter().map(|&v| v.ln()).sum::<f64>() / n as f64).exp();
            if mean == 0.0 { 0.0 } else { 1.0 - geo_mean / mean }
        };
        serde_json::json!({"folder": folder, "atkinson_attachment_count": atkinson, "message_count": cnt})
    }).collect();
    Ok(Json(serde_json::json!({"rows": result})))
}

