/// GET /mail/messages/stats/draft-rate-by-folder — taxa de rascunhos por pasta. Sprint #2247.
async fn draft_rate_by_folder_stats(
    State(state): State<AppState>,
    ctx:          RequestCtx,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    let mut tx = begin_tenant_tx(state.db(), ctx.tenant_id).await?;
    let rows: Vec<(String, i64, i64)> = sqlx::query_as(
        "SELECT mb.name AS folder_name, \
         COUNT(*) FILTER (WHERE m.flags @> ARRAY['\\\\Draft'])::BIGINT AS draft_count, \
         COUNT(*)::BIGINT AS message_count \
         FROM messages m JOIN mailboxes mb ON mb.id = m.mailbox_id \
         WHERE m.tenant_id = $1 AND mb.tenant_id = $1 AND mb.user_id = $2 \
         GROUP BY mb.name ORDER BY draft_count DESC",
    ).bind(ctx.tenant_id).bind(ctx.user_id).fetch_all(&mut *tx).await?;
    tx.commit().await?;
    let result: Vec<serde_json::Value> = rows.into_iter()
        .map(|(folder, draft, total)| {
            let rate = if total > 0 { draft as f64 / total as f64 } else { 0.0 };
            serde_json::json!({"folder_name": folder, "draft_count": draft, "message_count": total, "draft_rate": rate})
        })
        .collect();
    Ok(Json(serde_json::json!({"rows": result})))
}

