async fn cc_count_above_p90_by_tier(
    State(state): State<AppState>,
    ctx: RequestCtx,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    let mut tx = begin_tenant_tx(state.db(), ctx.tenant_id).await?;
    let rows: Vec<(String, Option<f64>, i64, i64)> = sqlx::query_as(
        "WITH tier_p90 AS ( \
             SELECT CASE WHEN m.size = 0 THEN 'empty' WHEN m.size < 1024 THEN 'tiny' WHEN m.size < 10240 THEN 'small' WHEN m.size < 102400 THEN 'medium' ELSE 'large' END AS tier, \
                    PERCENTILE_CONT(0.90) WITHIN GROUP (ORDER BY COALESCE(array_length(m.cc, 1), 0))::FLOAT8 AS p90_cc \
             FROM messages m WHERE m.tenant_id = $1 AND m.user_id = $2 GROUP BY tier \
         ) \
         SELECT t.tier, t.p90_cc, \
                COUNT(*) FILTER (WHERE COALESCE(array_length(m.cc, 1), 0) > t.p90_cc)::BIGINT AS count_above_p90, \
                COUNT(*)::BIGINT AS msg_count \
         FROM messages m \
         JOIN tier_p90 t ON (CASE WHEN m.size = 0 THEN 'empty' WHEN m.size < 1024 THEN 'tiny' WHEN m.size < 10240 THEN 'small' WHEN m.size < 102400 THEN 'medium' ELSE 'large' END) = t.tier \
         WHERE m.tenant_id = $1 AND m.user_id = $2 GROUP BY t.tier, t.p90_cc ORDER BY t.tier",
    ).bind(ctx.tenant_id).bind(ctx.user_id).fetch_all(&mut *tx).await
    .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    tx.commit().await.map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    let result = rows.into_iter().map(|(tier, p90, above, cnt)| serde_json::json!({"tier": tier, "p90_cc_count": p90, "count_above_p90": above, "message_count": cnt})).collect::<Vec<_>>();
    Ok(Json(serde_json::json!({"rows": result})))
}

