/// GET /mail/messages/stats/bcc-count-harmonic-mean-by-folder — média harmônica de bcc_count × folder. Sprint #4315.
async fn bcc_count_harmonic_mean_by_folder_stats(
    State(state): State<AppState>,
    ctx: RequestCtx,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    let mut tx = begin_tenant_tx(state.db(), ctx.tenant_id).await?;
    let rows: Vec<(String, Option<f64>, Option<f64>, i64)> = sqlx::query_as(
        "SELECT mb.name AS folder, \
                COUNT(*) FILTER (WHERE COALESCE(array_length(m.bcc, 1), 0) > 0)::FLOAT8 AS valid_n, \
                SUM(1.0 / NULLIF(COALESCE(array_length(m.bcc, 1), 0), 0))::FLOAT8 AS inv_sum, \
                COUNT(*)::BIGINT AS msg_count \
         FROM messages m JOIN mailboxes mb ON m.mailbox_id = mb.id \
         WHERE m.tenant_id = $1 AND m.user_id = $2 \
         GROUP BY mb.name ORDER BY mb.name",
    ).bind(ctx.tenant_id).bind(ctx.user_id).fetch_all(&mut *tx).await
    .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    tx.commit().await.map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    let result = rows.into_iter().map(|(folder, valid_n, inv_sum, cnt)| {
        let hm = match (valid_n, inv_sum) {
            (Some(n), Some(s)) if s > 0.0 => Some(n / s),
            _ => None,
        };
        serde_json::json!({"folder": folder, "harmonic_mean_bcc_count": hm, "message_count": cnt})
    }).collect::<Vec<_>>();
    Ok(Json(serde_json::json!({"rows": result})))
}

