async fn subject_word_count_above_mean_by_tier(
    State(state): State<AppState>, ctx: RequestCtx,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    let mut tx = begin_tenant_tx(state.db(), ctx.tenant_id).await
        .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    let rows: Vec<(String, i64, i64)> = sqlx::query_as(
        "WITH tier_mean AS ( \
             SELECT CASE WHEN m.size = 0 THEN 'empty' WHEN m.size < 1024 THEN 'tiny' WHEN m.size < 10240 THEN 'small' WHEN m.size < 102400 THEN 'medium' ELSE 'large' END AS tier, \
                    AVG(COALESCE(array_length(regexp_split_to_array(TRIM(COALESCE(m.subject, '')), '\\s+'), 1), 0))::FLOAT8 AS mean_swc \
             FROM messages m WHERE m.tenant_id = $1 AND m.user_id = $2 GROUP BY tier \
         ) \
         SELECT t.tier, \
                COUNT(*) FILTER (WHERE COALESCE(array_length(regexp_split_to_array(TRIM(COALESCE(m.subject, '')), '\\s+'), 1), 0) > t.mean_swc)::BIGINT AS count_above_mean, \
                COUNT(*)::BIGINT AS msg_count \
         FROM messages m \
         JOIN tier_mean t ON (CASE WHEN m.size = 0 THEN 'empty' WHEN m.size < 1024 THEN 'tiny' WHEN m.size < 10240 THEN 'small' WHEN m.size < 102400 THEN 'medium' ELSE 'large' END) = t.tier \
         WHERE m.tenant_id = $1 AND m.user_id = $2 GROUP BY t.tier ORDER BY t.tier",
    ).bind(ctx.tenant_id).bind(ctx.user_id).fetch_all(&mut *tx).await
    .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    tx.commit().await.map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    let result = rows.into_iter().map(|(tier, above, cnt)| serde_json::json!({"tier": tier, "count_above_mean_subject_word_count": above, "message_count": cnt})).collect::<Vec<_>>();
    Ok(Json(serde_json::json!({"rows": result})))
}

