async fn sent_at_age_count_above_mean_by_folder(
    State(state): State<AppState>, ctx: RequestCtx,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    let mut tx = begin_tenant_tx(state.db(), ctx.tenant_id).await
        .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    let rows: Vec<(String, i64, i64)> = sqlx::query_as(
        "WITH folder_mean AS ( \
             SELECT mb.name AS folder, \
                    AVG(EXTRACT(EPOCH FROM (NOW() - m.sent_at)))::FLOAT8 AS mean_saa \
             FROM messages m JOIN mailboxes mb ON m.mailbox_id = mb.id \
             WHERE m.tenant_id = $1 AND m.user_id = $2 AND m.sent_at IS NOT NULL GROUP BY mb.name \
         ) \
         SELECT f.folder, \
                COUNT(*) FILTER (WHERE EXTRACT(EPOCH FROM (NOW() - m.sent_at)) > f.mean_saa)::BIGINT AS count_above_mean, \
                COUNT(*)::BIGINT AS msg_count \
         FROM messages m \
         JOIN mailboxes mb ON m.mailbox_id = mb.id \
         JOIN folder_mean f ON mb.name = f.folder \
         WHERE m.tenant_id = $1 AND m.user_id = $2 AND m.sent_at IS NOT NULL GROUP BY f.folder ORDER BY f.folder",
    ).bind(ctx.tenant_id).bind(ctx.user_id).fetch_all(&mut *tx).await
    .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    tx.commit().await.map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    let result = rows.into_iter().map(|(folder, above, cnt)| serde_json::json!({"folder": folder, "count_above_mean_sent_at_age": above, "message_count": cnt})).collect::<Vec<_>>();
    Ok(Json(serde_json::json!({"rows": result})))
}

