    let rows: Vec<(String, i64, i64)> = sqlx::query_as(
        "WITH folder_mean AS ( \
             SELECT mb.name AS folder, AVG(LENGTH(COALESCE(m.x_forwarded_for, '')))::FLOAT8 AS mean_xff \
             FROM messages m JOIN mailboxes mb ON m.mailbox_id = mb.id \
             WHERE m.tenant_id = $1 AND m.user_id = $2 GROUP BY mb.name \
         ) \
         SELECT f.folder, \
                COUNT(*) FILTER (WHERE LENGTH(COALESCE(m.x_forwarded_for, '')) > f.mean_xff)::BIGINT AS count_above_mean, \
                COUNT(*)::BIGINT AS msg_count \
         FROM messages m \
         JOIN mailboxes mb ON m.mailbox_id = mb.id \
         JOIN folder_mean f ON mb.name = f.folder \
         WHERE m.tenant_id = $1 AND m.user_id = $2 GROUP BY f.folder ORDER BY f.folder",
    ).bind(ctx.tenant_id).bind(ctx.user_id).fetch_all(&mut *tx).await
    .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    tx.commit().await.map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    let result = rows.into_iter().map(|(folder, above, cnt)| serde_json::json!({"folder": folder, "count_above_mean_x_forwarded_for_length": above, "message_count": cnt})).collect::<Vec<_>>();
