pub async fn to_addrs_count_count_above_mean_by_tier(
    State(state): State<AppState>, ctx: RequestCtx,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    let mut tx = begin_tenant_tx(state.db(), ctx.tenant_id).await
        .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    let rows: Vec<(String, Option<f64>, i64, i64)> = sqlx::query_as(
        "WITH tier_avg AS ( \
             SELECT CASE WHEN m.size = 0 THEN 'empty' WHEN m.size < 1024 THEN 'tiny' WHEN m.size < 10240 THEN 'small' WHEN m.size < 102400 THEN 'medium' WHEN m.size < 1048576 THEN 'large' ELSE 'huge' END AS tier, \
                    AVG(COALESCE(jsonb_array_length(m.to_addrs), 0))::FLOAT8 AS mean_tac \
             FROM messages m WHERE m.tenant_id = $1 AND m.user_id = $2 GROUP BY tier \
         ) \
         SELECT t.tier, t.mean_tac, \
                COUNT(*) FILTER (WHERE COALESCE(jsonb_array_length(m.to_addrs), 0) > t.mean_tac)::BIGINT AS count_above, \
                COUNT(*)::BIGINT AS msg_count \
         FROM messages m \
         JOIN tier_avg t ON (CASE WHEN m.size = 0 THEN 'empty' WHEN m.size < 1024 THEN 'tiny' WHEN m.size < 10240 THEN 'small' WHEN m.size < 102400 THEN 'medium' WHEN m.size < 1048576 THEN 'large' ELSE 'huge' END) = t.tier \
         WHERE m.tenant_id = $1 AND m.user_id = $2 GROUP BY t.tier, t.mean_tac ORDER BY t.tier",
    ).bind(ctx.tenant_id).bind(ctx.user_id).fetch_all(&mut *tx).await
    .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    tx.commit().await.map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    let result = rows.into_iter().map(|(tier, mean, above, cnt)| serde_json::json!({"tier": tier, "mean_to_addrs_count": mean, "count_above_mean": above, "message_count": cnt})).collect::<Vec<_>>();
    Ok(Json(serde_json::json!({"rows": result})))
}

