pub async fn date_quarter_above_mean_by_folder(
    State(state): State<AppState>, ctx: RequestCtx,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    let mut tx = begin_tenant_tx(state.db(), ctx.tenant_id).await
        .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    let rows: Vec<(String, Option<f64>, i64, i64)> = sqlx::query_as(
        "WITH folder_avg AS ( \
             SELECT mb.name AS folder, AVG(EXTRACT(QUARTER FROM m.date))::FLOAT8 AS mean_f \
             FROM messages m JOIN mailboxes mb ON m.mailbox_id = mb.id \
             WHERE m.tenant_id = $1 AND m.user_id = $2 GROUP BY mb.name \
         ) \
         SELECT f.folder, f.mean_f, \
                COUNT(*) FILTER (WHERE EXTRACT(QUARTER FROM m.date) > f.mean_f)::BIGINT AS count_above, \
                COUNT(*)::BIGINT AS msg_count \
         FROM messages m JOIN mailboxes mb ON m.mailbox_id = mb.id \
         JOIN folder_avg f ON mb.name = f.folder \
         WHERE m.tenant_id = $1 AND m.user_id = $2 GROUP BY f.folder, f.mean_f ORDER BY f.folder",
    ).bind(ctx.tenant_id).bind(ctx.user_id).fetch_all(&mut *tx).await
    .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    tx.commit().await.map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    let result = rows.into_iter().map(|(folder, mean, above, cnt)| serde_json::json!({"folder": folder, "mean_date_quarter": mean, "count_above_mean": above, "message_count": cnt})).collect::<Vec<_>>();
    Ok(Json(serde_json::json!({"rows": result})))
}

