pub async fn vacation_subject_length_count_above_mean_by_tier(
    State(state): State<AppState>, ctx: RequestCtx,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    let mut tx = begin_tenant_tx(state.db(), ctx.tenant_id).await
        .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    let rows: Vec<(String, Option<f64>, i64, i64)> = sqlx::query_as(
        "WITH user_tier AS ( \
             SELECT u.id AS uid, CASE WHEN COALESCE(SUM(mb.size_bytes), 0) = 0 THEN 'empty' WHEN COALESCE(SUM(mb.size_bytes), 0) < 1048576 THEN 'tiny' WHEN COALESCE(SUM(mb.size_bytes), 0) < 10485760 THEN 'small' WHEN COALESCE(SUM(mb.size_bytes), 0) < 104857600 THEN 'medium' WHEN COALESCE(SUM(mb.size_bytes), 0) < 1073741824 THEN 'large' ELSE 'huge' END AS tier \
             FROM users u LEFT JOIN mailboxes mb ON mb.user_id = u.id AND mb.tenant_id = $1 \
             WHERE u.id = $2 GROUP BY u.id \
         ), \
         tier_avg AS ( \
             SELECT ut.tier, AVG(LENGTH(v.subject))::FLOAT8 AS mean_f \
             FROM user_vacation v JOIN user_tier ut ON v.user_id = ut.uid \
             WHERE v.tenant_id = $1 GROUP BY ut.tier \
         ) \
         SELECT t.tier, t.mean_f, \
                COUNT(*) FILTER (WHERE LENGTH(v.subject) > t.mean_f)::BIGINT AS count_above, \
                COUNT(*)::BIGINT AS vacation_count \
         FROM user_vacation v JOIN user_tier ut ON v.user_id = ut.uid \
         JOIN tier_avg t ON ut.tier = t.tier \
         WHERE v.tenant_id = $1 GROUP BY t.tier, t.mean_f ORDER BY t.tier",
    ).bind(ctx.tenant_id).bind(ctx.user_id).fetch_all(&mut *tx).await
    .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    tx.commit().await.map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    let result = rows.into_iter().map(|(tier, mean, above, cnt)| serde_json::json!({"tier": tier, "mean_vacation_subject_length": mean, "count_above_mean": above, "vacation_count": cnt})).collect::<Vec<_>>();
    Ok(Json(serde_json::json!({"rows": result})))
}

pub async fn vacation_subject_length_count_below_mean_by_tier(
    State(state): State<AppState>, ctx: RequestCtx,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    let mut tx = begin_tenant_tx(state.db(), ctx.tenant_id).await
        .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    let rows: Vec<(String, Option<f64>, i64, i64)> = sqlx::query_as(
        "WITH user_tier AS ( \
             SELECT u.id AS uid, CASE WHEN COALESCE(SUM(mb.size_bytes), 0) = 0 THEN 'empty' WHEN COALESCE(SUM(mb.size_bytes), 0) < 1048576 THEN 'tiny' WHEN COALESCE(SUM(mb.size_bytes), 0) < 10485760 THEN 'small' WHEN COALESCE(SUM(mb.size_bytes), 0) < 104857600 THEN 'medium' WHEN COALESCE(SUM(mb.size_bytes), 0) < 1073741824 THEN 'large' ELSE 'huge' END AS tier \
             FROM users u LEFT JOIN mailboxes mb ON mb.user_id = u.id AND mb.tenant_id = $1 \
             WHERE u.id = $2 GROUP BY u.id \
         ), \
         tier_avg AS ( \
             SELECT ut.tier, AVG(LENGTH(v.subject))::FLOAT8 AS mean_f \
             FROM user_vacation v JOIN user_tier ut ON v.user_id = ut.uid \
             WHERE v.tenant_id = $1 GROUP BY ut.tier \
         ) \
         SELECT t.tier, t.mean_f, \
                COUNT(*) FILTER (WHERE LENGTH(v.subject) < t.mean_f)::BIGINT AS count_below, \
                COUNT(*)::BIGINT AS vacation_count \
         FROM user_vacation v JOIN user_tier ut ON v.user_id = ut.uid \
         JOIN tier_avg t ON ut.tier = t.tier \
         WHERE v.tenant_id = $1 GROUP BY t.tier, t.mean_f ORDER BY t.tier",
    ).bind(ctx.tenant_id).bind(ctx.user_id).fetch_all(&mut *tx).await
    .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    tx.commit().await.map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    let result = rows.into_iter().map(|(tier, mean, below, cnt)| serde_json::json!({"tier": tier, "mean_vacation_subject_length": mean, "count_below_mean": below, "vacation_count": cnt})).collect::<Vec<_>>();
    Ok(Json(serde_json::json!({"rows": result})))
}

pub async fn vacation_subject_length_count_above_mean_by_folder(
    State(state): State<AppState>, ctx: RequestCtx,
) -> Result<Json<serde_json::Value>, (StatusCode, Json<serde_json::Value>)> {
    let mut tx = begin_tenant_tx(state.db(), ctx.tenant_id).await
        .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    let rows: Vec<(String, Option<f64>, i64, i64)> = sqlx::query_as(
        "WITH vacation_avg AS ( \
             SELECT AVG(LENGTH(v.subject))::FLOAT8 AS mean_f \
             FROM user_vacation v WHERE v.tenant_id = $1 \
         ) \
         SELECT 'all_users'::TEXT AS folder, va.mean_f, \
                COUNT(*) FILTER (WHERE LENGTH(v.subject) > va.mean_f)::BIGINT AS count_above, \
                COUNT(*)::BIGINT AS vacation_count \
         FROM user_vacation v CROSS JOIN vacation_avg va \
         WHERE v.tenant_id = $1 GROUP BY va.mean_f",
    ).bind(ctx.tenant_id).bind(ctx.user_id).fetch_all(&mut *tx).await
    .map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    tx.commit().await.map_err(|e| (StatusCode::INTERNAL_SERVER_ERROR, Json(serde_json::json!({"error": e.to_string()}))))?;
    let result = rows.into_iter().map(|(folder, mean, above, cnt)| serde_json::json!({"folder": folder, "mean_vacation_subject_length": mean, "count_above_mean": above, "vacation_count": cnt})).collect::<Vec<_>>();
    Ok(Json(serde_json::json!({"rows": result})))
}

